                'ಪಾಲಿಸಿಸ್ಟಿಕ್ ಅಂಡಾಶಯ ಸಿಂಡ್ರೋಮ್ (PCOS) ಸಂತಾನೋತ್ಪತ್ತಿ ವಯಸ್ಸಿನ ಹತ್ತು ಮಹಿಳೆಯರಲ್ಲಿ ಒಬ್ಬರನ್ನು ಬಾಧಿಸುವ ಸಾಮಾನ್ಯ ಹಾರ್ಮೋನ್ ಸ್ಥಿತಿಯಾಗಿದೆ. ಇದು ಅನಿಯಮಿತ ಮುಟ್ಟು, ಹೆಚ್ಚಿನ androgen ಮಟ್ಟಗಳು ಮತ್ತು ಅಂಡಾಶಯಗಳ ಮೇಲೆ ಅನೇಕ ಸಣ್ಣ follicles ಗಳಿಂದ ಗುರುತಿಸಲ್ಪಡುತ್ತದೆ.',
          },
          {
            'title': 'ಇನ್ಸುಲಿನ್ ಪ್ರತಿರೋಧದ ಪಾತ್ರ',
            'body':
