            'title': 'ಮೌಖಿಕ ಗರ್ಭನಿರೋಧಕ ಮಾತ್ರೆಗಳು ಎಂದರೇನು?',
            'body':
                'ಮೌಖಿಕ ಗರ್ಭನಿರೋಧಕ ಮಾತ್ರೆಗಳು ಗರ್ಭಧಾರಣೆಯನ್ನು ತಡೆಯಲು ಕೃತಕ ಹಾರ್ಮೋನ್‌ಗಳನ್ನು ಹೊಂದಿರುವ ದೈನಂದಿನ ಮಾತ್ರೆಗಳಾಗಿವೆ. ಇವು ವಿಶ್ವಾದ್ಯಂತ ಅತ್ಯಂತ ವ್ಯಾಪಕವಾಗಿ ಬಳಸಲಾಗುವ ಮತ್ತು ಪರಿಣಾಮಕಾರಿ ಹಿಂತಿರುಗಿಸಬಹುದಾದ ಗರ್ಭನಿರೋಧಕ ವಿಧಾನಗಳಲ್ಲಿ ಒಂದಾಗಿದೆ.',
          },
          {
            'title': 'ಸಂಯೋಜಿತ ಮಾತ್ರೆ vs. Progestogen-ಮಾತ್ರ ಮಾತ್ರೆ',
            'body':
                'ಸಂಯೋಜಿತ ಮಾತ್ರೆಗಳಲ್ಲಿ oestrogen ಮತ್ತು progestogen ಎರಡೂ ಇರುತ್ತವೆ, ಆದರೆ mini-pill ನಲ್ಲಿ ಕೇವಲ progestogen ಮಾತ್ರ ಇರುತ್ತದೆ. ನಿಮ್ಮ ವಯಸ್ಸು, ಆರೋಗ್ಯ ಇತಿಹಾಸ ಮತ್ತು ಜೀವನಶೈಲಿಯ ಆಧಾರದ ಮೇಲೆ ನಿಮ್ಮ ವೈದ್ಯರು ಸೂಕ್ತವಾದ ವಿಧವನ್ನು ಶಿಫಾರಸು ಮಾಡುತ್ತಾರೆ.',
          },
          {
            'title': 'ಅವು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತವೆ',
            'body':
                'ಮಾತ್ರೆಯು ಪ್ರಾಥಮಿಕವಾಗಿ ಅಂಡೋತ್ಪತ್ತಿಯನ್ನು (ovulation) ತಡೆಯುತ್ತದೆ, ಇದರಿಂದ ಪ್ರತಿ ತಿಂಗಳು ಅಂಡಾಣು ಬಿಡುಗಡೆಯಾಗುವುದಿಲ್ಲ. ಇದು ಗರ್ಭಕಂಠದ ಲೋಳೆಯನ್ನು ದಪ್ಪಗೊಳಿಸಿ ವೀರ್ಯಾಣುಗಳನ್ನು ತಡೆಯುತ್ತದೆ ಮತ್ತು ಗರ್ಭಾಶಯದ ಒಳಪದರವನ್ನು ತೆಳುಗೊಳಿಸಿ ಅಂಡ ಸ್ಥಾಪನೆಯ ಸಾಧ್ಯತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.',
          },
          {
            'title': 'ಪರಿಣಾಮಕಾರಿತ್ವ',
            'body':
                'ಪರಿಪೂರ್ಣವಾಗಿ ಬಳಸಿದಾಗ, ಮಾತ್ರೆಯು 99 ಪ್ರತಿಶತಕ್ಕಿಂತ ಹೆಚ್ಚು ಪರಿಣಾಮಕಾರಿಯಾಗಿದೆ. ಸಾಮಾನ್ಯ ದೈನಂದಿನ ಬಳಕೆಯಲ್ಲಿ, ಮಾತ್ರೆಗಳನ್ನು ಮರೆಯುವ ಅಥವಾ ಇತರ ಔಷಧಗಳೊಂದಿಗಿನ ಪರಸ್ಪರ ಕ್ರಿಯೆಯಿಂದಾಗಿ ಪರಿಣಾಮಕಾರಿತ್ವ ಸುಮಾರು 91 ಪ್ರತಿಶತಕ್ಕೆ ಇಳಿಯುತ್ತದೆ.',
          },
          {
            'title': 'ಗರ್ಭನಿರೋಧಕೇತರ ಪ್ರಯೋಜನಗಳು',
            'body':
                'ಮಾತ್ರೆಯು ಮುಟ್ಟನ್ನು ನಿಯಮಿತಗೊಳಿಸಲು, ಮುಟ್ಟಿನ ನೋವು ಮತ್ತು ಅಧಿಕ ರಕ್ತಸ್ರಾವವನ್ನು ಕಡಿಮೆ ಮಾಡಲು, ಮೊಡವೆಯನ್ನು ಸುಧಾರಿಸಲು ಮತ್ತು ಅಂಡಾಶಯ ಹಾಗೂ ಗರ್ಭಾಶಯದ ಒಳಪದರದ ಕ್ಯಾನ್ಸರ್‌ನ ಅಪಾಯವನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಸಹಾಯ ಮಾಡಬಹುದು.',
          },
          {
            'title': 'ಸಂಭಾವ್ಯ ಅಡ್ಡ ಪರಿಣಾಮಗಳು',
