                'ಧೂಮಪಾನ ಮಾಡುವ ಮತ್ತು 35 ವರ್ಷ ಮೇಲ್ಪಟ್ಟ ಮಹಿಳೆಯರಿಗೆ, ಅಥವಾ ರಕ್ತ ಹೆಪ್ಪುಗಟ್ಟುವಿಕೆ ಅಥವಾ ಕೆಲವು ಮೈಗ್ರೇನ್‌ಗಳ ಇತಿಹಾಸ ಹೊಂದಿರುವವರಿಗೆ ಸಂಯೋಜಿತ ಮಾತ್ರೆಯನ್ನು ಶಿಫಾರಸು ಮಾಡಲಾಗುವುದಿಲ್ಲ. ಯಾವುದೇ ಹಾರ್ಮೋನ್ ಗರ್ಭನಿರೋಧಕವನ್ನು ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು ನಿಮ್ಮ ಸಂಪೂರ್ಣ ವೈದ್ಯಕೀಯ ಇತಿಹಾಸವನ್ನು ವೈದ್ಯರಿಗೆ ತಿಳಿಸಿ.',
