      'injectable-implant-contraceptives': const EducationTopicData(
        titleEn: 'Injectable & Implant Contraceptives',
        titleKn: 'ಚುಚ್ಚುಮದ್ದು ಮತ್ತು ಅಳವಡಿಕೆ ಗರ್ಭನಿರೋಧಕಗಳು',
        sectionsEn: [
          {
            'title': 'What Are Injectable Contraceptives?',
