            'body':
                'ಚುಚ್ಚುಮದ್ದು ಗರ್ಭನಿರೋಧಕಗಳು ಗರ್ಭಧಾರಣೆಯನ್ನು ತಡೆಯಲು ನಿಯಮಿತ ಅಂತರದಲ್ಲಿ, ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರತಿ 12 ರಿಂದ 13 ವಾರಗಳಿಗೊಮ್ಮೆ ನೀಡಲಾಗುವ progestogen-ಆಧಾರಿತ ಚುಚ್ಚುಮದ್ದುಗಳಾಗಿವೆ. ಅತ್ಯಂತ ಸಾಮಾನ್ಯವಾಗಿ ಬಳಸಲಾಗುವ ಚುಚ್ಚುಮದ್ದು depot medroxyprogesterone acetate (DMPA) ಆಗಿದೆ.',
