                'ಅಳವಡಿಕೆ ಎಂದರೆ ಮೇಲ್ಭಾಗದ ತೋಳಿನ ಚರ್ಮದ ಕೆಳಗೆ ಸೇರಿಸಲಾಗುವ ಬೆಂಕಿಪೊಟ್ಟಣದ ಕಡ್ಡಿಯ ಗಾತ್ರದ ಸಣ್ಣ ಮೃದು ಕೋಲು. ಇದು ಸ್ಥಿರವಾದ ಕಡಿಮೆ ಪ್ರಮಾಣದ progestogen ಅನ್ನು ಬಿಡುಗಡೆ ಮಾಡುತ್ತದೆ ಮತ್ತು ಮೂರು ವರ್ಷಗಳವರೆಗೆ ಅತ್ಯಂತ ಪರಿಣಾಮಕಾರಿ ಗರ್ಭನಿರೋಧನೆಯನ್ನು ಒದಗಿಸುತ್ತದೆ.',
          },
          {
            'title': 'ಅವು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತವೆ',
            'body':
