                'ಬಹುತೇಕ ಎಲ್ಲಾ ಗರ್ಭಕಂಠದ ಕ್ಯಾನ್ಸರ್‌ಗಳು ಹೆಚ್ಚಿನ ಅಪಾಯದ HPV ತಳಿಗಳ ನಿರಂತರ ಸೋಂಕಿನಿಂದ ಉಂಟಾಗುತ್ತವೆ. ಹೆಚ್ಚಿನ HPV ಸೋಂಕುಗಳು ತಾವಾಗಿಯೇ ಸರಿಹೋಗುತ್ತವೆ, ಆದರೆ ನಿಯಮಿತ ಸ್ಕ್ರೀನಿಂಗ್ ಕ್ಯಾನ್ಸರ್‌ಪೂರ್ವ ಬದಲಾವಣೆಗಳಿಗೆ ಮುಂದುವರಿಯುವ ಕಡಿಮೆ ಸಂಖ್ಯೆಯ ಸೋಂಕುಗಳನ್ನು ಗುರುತಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
