          },
          {
            'title': 'Understanding Your T-Score',
            'body':
                'Results are reported as a T-score that compares your bone density to that of a healthy young adult. A T-score above minus one is normal, between minus one and minus 2.5 indicates osteopenia (low bone mass), and below minus 2.5 indicates osteoporosis.',
