                'ಭಾರ-ಹೊರುವ ವ್ಯಾಯಾಮ, ಸಾಕಷ್ಟು calcium ಮತ್ತು vitamin D ಸೇವನೆ, ಧೂಮಪಾನ ತ್ಯಜಿಸುವುದು ಮತ್ತು ಮದ್ಯಪಾನ ಮಿತಿಗೊಳಿಸುವುದು ಮೂಳೆ ಶಕ್ತಿಯನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಲು ಸಹಾಯ ಮಾಡಬಹುದು. ನಿಮ್ಮ ಮೂಳೆ ಸಾಂದ್ರತೆ ಚಿಕಿತ್ಸೆಗೆ ಅಗತ್ಯವಾಗುವಷ್ಟು ಕಡಿಮೆಯಿದ್ದರೆ ಔಷಧಗಳನ್ನು ಸೂಚಿಸಬಹುದು.',
          },
          {
