            'body':
                'ಋತುಬಂಧಪೂರ್ವ ಮಹಿಳೆಯರಲ್ಲಿ ಅಧಿಕ ಮುಟ್ಟಿನ ರಕ್ತಸ್ರಾವ ಕಬ್ಬಿಣದ ಕೊರತೆಯ ಪ್ರಮುಖ ಕಾರಣ. ಇತರ ಕಾರಣಗಳಲ್ಲಿ ಆಹಾರದಲ್ಲಿ ಸಾಕಷ್ಟು ಕಬ್ಬಿಣ ಇಲ್ಲದಿರುವುದು, ಗರ್ಭಧಾರಣೆ ಮತ್ತು coeliac disease ನಂತಹ ಕಬ್ಬಿಣ ಹೀರಿಕೊಳ್ಳುವಿಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುವ ಸ್ಥಿತಿಗಳು ಸೇರಿವೆ.',
