            'title': 'ವ್ಯಾಯಾಮ ಹಾರ್ಮೋನ್‌ಗಳ ಮೇಲೆ ಹೇಗೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ',
            'body':
                'ನಿಯಮಿತ ದೈಹಿಕ ಚಟುವಟಿಕೆ insulin, cortisol, oestrogen ಮತ್ತು thyroid hormones ಸೇರಿದಂತೆ ಪ್ರಮುಖ ಹಾರ್ಮೋನ್‌ಗಳನ್ನು ನಿಯಂತ್ರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ವ್ಯಾಯಾಮ ಹಾರ್ಮೋನ್ ಸಮತೋಲನವನ್ನು ಸುಧಾರಿಸುತ್ತದೆ, ಇದು ಹೆಚ್ಚು ನಿಯಮಿತ ಮುಟ್ಟಿನ ಚಕ್ರಗಳಿಗೆ ಮತ್ತು ಉತ್ತಮ ಒಟ್ಟಾರೆ ಯೋಗಕ್ಷೇಮಕ್ಕೆ ಕಾರಣವಾಗಬಹುದು.',
          },
          {
            'title': 'ಮುಟ್ಟಿನ ಆರೋಗ್ಯಕ್ಕೆ ಪ್ರಯೋಜನಗಳು',
            'body':
                'ಮಧ್ಯಮ ವ್ಯಾಯಾಮ ಮುಟ್ಟಿನ ನೋವು, ಮುಟ್ಟಿನ ಮೊದಲಿನ ಲಕ್ಷಣಗಳು ಮತ್ತು ಉಬ್ಬರದ ತೀವ್ರತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು. PCOS ಹೊಂದಿರುವ ಮಹಿಳೆಯರು ವಿಶೇಷವಾಗಿ ಪ್ರಯೋಜನ ಪಡೆಯುತ್ತಾರೆ, ಏಕೆಂದರೆ ದೈಹಿಕ ಚಟುವಟಿಕೆ insulin ಸಂವೇದನಶೀಲತೆಯನ್ನು ಸುಧಾರಿಸುತ್ತದೆ ಮತ್ತು ನಿಯಮಿತ ಅಂಡೋತ್ಪತ್ತಿಯನ್ನು ಮರಳಿ ತರಲು ಸಹಾಯ ಮಾಡಬಹುದು.',
