          {
            'title': 'ಶಿಫಾರಸು ಮಾಡಿದ ವ್ಯಾಯಾಮ ವಿಧಗಳು',
            'body':
                'ಏರೋಬಿಕ್ ವ್ಯಾಯಾಮ (ವೇಗದ ನಡಿಗೆ, ಈಜು ಅಥವಾ ಸೈಕ್ಲಿಂಗ್), ಶಕ್ತಿ ತರಬೇತಿ ಮತ್ತು ನಮ್ಯತೆ ಕೆಲಸದ ಸಂಯೋಜನೆ ಅತ್ಯಂತ ಹೆಚ್ಚಿನ ಪ್ರಯೋಜನ ನೀಡುತ್ತದೆ. ವಾರಕ್ಕೆ ಕನಿಷ್ಠ 150 ನಿಮಿಷಗಳ ಮಧ್ಯಮ-ತೀವ್ರತೆಯ ಚಟುವಟಿಕೆಯನ್ನು ಗುರಿಯಾಗಿಸಿ.',
          },
          {
