        sectionsEn: [
          {
            'title': 'What Is Postpartum Depression?',
            'body':
                'Postpartum depression (PPD) is a serious mood disorder that can develop in the weeks or months after giving birth. It is more than the "baby blues" and requires professional treatment to resolve.',
          },
          {
            'title': 'Difference from Baby Blues',
            'body':
                'Baby blues are common and usually resolve within two weeks of delivery, involving mild mood swings, tearfulness, and anxiety. Postpartum depression is more intense, lasts longer, and significantly interferes with daily functioning and bonding with the baby.',
