            'title': 'ಪ್ರಸವಾನಂತರದ ಖಿನ್ನತೆ ಎಂದರೇನು?',
            'body':
                'ಪ್ರಸವಾನಂತರದ ಖಿನ್ನತೆ (PPD) ಎಂಬುದು ಹೆರಿಗೆಯ ನಂತರ ವಾರಗಳು ಅಥವಾ ತಿಂಗಳುಗಳಲ್ಲಿ ಬೆಳೆಯಬಹುದಾದ ಗಂಭೀರವಾದ ಮನೋಸ್ಥಿತಿ ಅಸ್ವಸ್ಥತೆಯಾಗಿದೆ. ಇದು "baby blues" ಗಿಂತ ಹೆಚ್ಚಿನದಾಗಿದ್ದು, ಪರಿಹಾರಕ್ಕೆ ವೃತ್ತಿಪರ ಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯವಿರುತ್ತದೆ.',
          },
          {
            'title': 'Baby Blues ನಿಂದ ವ್ಯತ್ಯಾಸ',
            'body':
                'Baby blues ಸಾಮಾನ್ಯವಾಗಿದ್ದು, ಹೆರಿಗೆಯ ಎರಡು ವಾರಗಳಲ್ಲಿ ಸರಿಯಾಗುತ್ತದೆ — ಇದರಲ್ಲಿ ಸೌಮ್ಯ ಮನೋಸ್ಥಿತಿ ಬದಲಾವಣೆ, ಅಳು ಮತ್ತು ಆತಂಕ ಸೇರಿವೆ. ಪ್ರಸವಾನಂತರದ ಖಿನ್ನತೆ ಹೆಚ್ಚು ತೀವ್ರವಾಗಿದ್ದು, ಹೆಚ್ಚು ಕಾಲ ಉಳಿಯುತ್ತದೆ ಮತ್ತು ದೈನಂದಿನ ಕಾರ್ಯನಿರ್ವಹಣೆ ಹಾಗೂ ಮಗುವಿನೊಂದಿಗೆ ಬಾಂಧವ್ಯ ಬೆಳೆಸುವುದರಲ್ಲಿ ಗಮನಾರ್ಹವಾಗಿ ಅಡ್ಡಿಯುಂಟುಮಾಡುತ್ತದೆ.',
          },
          {
            'title': 'ಸಾಮಾನ್ಯ ಲಕ್ಷಣಗಳು',
            'body':
                'ಲಕ್ಷಣಗಳಲ್ಲಿ ನಿರಂತರ ದುಃಖ, ಚಟುವಟಿಕೆಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಕಳೆದುಕೊಳ್ಳುವುದು, ಮಗುವಿನೊಂದಿಗೆ ಬಾಂಧವ್ಯ ಬೆಳೆಸಲು ಕಷ್ಟ, ಅಪರಾಧ ಅಥವಾ ನಿಷ್ಪ್ರಯೋಜಕತೆಯ ಭಾವನೆಗಳು, ನವಜಾತ ಶಿಶುವಿನೊಂದಿಗೆ ನಿರೀಕ್ಷಿತಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಹಸಿವು ಮತ್ತು ನಿದ್ರೆಯ ಬದಲಾವಣೆಗಳು, ಮತ್ತು ತೀವ್ರ ಸಂದರ್ಭಗಳಲ್ಲಿ ಸ್ವಯಂ-ಹಾನಿಯ ಆಲೋಚನೆಗಳು ಸೇರಿವೆ. ಈ ಲಕ್ಷಣಗಳು ಕ್ರಮೇಣ ಬೆಳೆಯಬಹುದು ಮತ್ತು ತಕ್ಷಣ ಗುರುತಿಸಲಾಗದಿರಬಹುದು.',
          },
          {
            'title': 'ಅಪಾಯಕಾರಿ ಅಂಶಗಳು',
            'body':
                'ವೈಯಕ್ತಿಕ ಅಥವಾ ಕುಟುಂಬದ ಖಿನ್ನತೆಯ ಇತಿಹಾಸ, ಸಾಮಾಜಿಕ ಬೆಂಬಲದ ಕೊರತೆ, ಜಟಿಲ ಗರ್ಭಧಾರಣೆ ಅಥವಾ ಹೆರಿಗೆ, ಮತ್ತು ಪ್ರಮುಖ ಜೀವನ ಒತ್ತಡಗಳು ಅಪಾಯವನ್ನು ಹೆಚ್ಚಿಸುತ್ತವೆ. ಆದಾಗ್ಯೂ, ಪ್ರಸವಾನಂತರದ ಖಿನ್ನತೆಯು ಪರಿಸ್ಥಿತಿಗಳ ಹೊರತಾಗಿಯೂ ಯಾವುದೇ ಹೊಸ ತಾಯಿಗೆ ಬರಬಹುದು.',
          },
          {
            'title': 'ಚಿಕಿತ್ಸಾ ಆಯ್ಕೆಗಳು',
