          },
          {
            'title': 'ತಕ್ಷಣ ಸಹಾಯ ಪಡೆಯಬೇಕಾದ ಸಂದರ್ಭ',
            'body':
                'ನಿಮಗೆ ಅಥವಾ ನಿಮ್ಮ ಮಗುವಿಗೆ ಹಾನಿ ಮಾಡುವ ಆಲೋಚನೆಗಳು ಬಂದರೆ, ಅಥವಾ ನಿಮ್ಮ ಮಗುವನ್ನು ನೋಡಿಕೊಳ್ಳಲು ಸಾಧ್ಯವಾಗದಂತೆ ಅನಿಸಿದರೆ, ತುರ್ತು ವೈದ್ಯಕೀಯ ಸಹಾಯ ಪಡೆಯಿರಿ. ಪ್ರಸವಾನಂತರದ ಖಿನ್ನತೆಗೆ ಚಿಕಿತ್ಸೆ ಲಭ್ಯವಿದೆ, ಮತ್ತು ಸಹಾಯ ಕೋರುವುದು ದೌರ್ಬಲ್ಯವಲ್ಲ, ಶಕ್ತಿಯ ಸಂಕೇತ.',
          },
        ],
      ),

      'premenstrual-mood-disorders': const EducationTopicData(
