        sectionsEn: [
          {
            'title': 'What Are Premenstrual Mood Disorders?',
            'body':
                'Premenstrual mood disorders include premenstrual syndrome (PMS) and premenstrual dysphoric disorder (PMDD). These conditions involve emotional and physical symptoms that occur in the second half of the menstrual cycle and resolve after the period begins.',
          },
          {
            'title': 'PMS vs. PMDD',
            'body':
                'PMS affects up to 75 percent of menstruating women with mild to moderate symptoms. PMDD is a more severe form affecting three to eight percent of women, causing significant mood disturbances such as severe depression, irritability, and anxiety that interfere with daily life.',
          },
          {
            'title': 'Common Symptoms',
            'body':
                'Emotional symptoms include mood swings, irritability, anxiety, sadness, and difficulty concentrating. Physical symptoms such as bloating, breast tenderness, headaches, and fatigue often accompany the mood changes.',
          },
          {
            'title': 'What Causes These Symptoms?',
            'body':
                'The exact cause is not fully understood, but it is thought to involve an abnormal sensitivity to normal hormonal fluctuations during the menstrual cycle. Changes in serotonin levels in the brain also play a significant role.',
          },
          {
            'title': 'Lifestyle Management',
            'body':
