        sectionsKn: [
          {
            'title': 'ಮುಟ್ಟಿನ ಮೊದಲಿನ ಮನೋಸ್ಥಿತಿ ಅಸ್ವಸ್ಥತೆಗಳು ಎಂದರೇನು?',
            'body':
                'ಮುಟ್ಟಿನ ಮೊದಲಿನ ಮನೋಸ್ಥಿತಿ ಅಸ್ವಸ್ಥತೆಗಳಲ್ಲಿ PMS (premenstrual syndrome) ಮತ್ತು PMDD (premenstrual dysphoric disorder) ಸೇರಿವೆ. ಈ ಸ್ಥಿತಿಗಳಲ್ಲಿ ಋತುಚಕ್ರದ ಎರಡನೇ ಅರ್ಧದಲ್ಲಿ ಭಾವನಾತ್ಮಕ ಮತ್ತು ದೈಹಿಕ ಲಕ್ಷಣಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ ಮತ್ತು ಮುಟ್ಟು ಪ್ರಾರಂಭವಾದ ನಂತರ ಕಡಿಮೆಯಾಗುತ್ತವೆ.',
