      'stress-hormonal-imbalance': const EducationTopicData(
        titleEn: 'Stress & Hormonal Imbalance',
        titleKn: 'ಒತ್ತಡ ಮತ್ತು ಹಾರ್ಮೋನ್ ಅಸಮತೋಲನ',
        sectionsEn: [
          {
            'title': 'How Stress Affects Hormones',
            'body':
                'When the body is under stress, the adrenal glands release cortisol and adrenaline. Chronic stress keeps cortisol levels elevated, which can disrupt the balance of reproductive hormones, thyroid function, and insulin regulation.',
          },
          {
            'title': 'Impact on Menstrual Cycles',
            'body':
