          },
          {
            'title': 'Stress and Fertility',
            'body':
                'Chronic stress can interfere with ovulation and reduce fertility, creating a difficult cycle since fertility struggles themselves can be a major source of stress. Addressing stress is an important part of a comprehensive approach to fertility care.',
          },
          {
            'title': 'Physical Symptoms of Chronic Stress',
            'body':
