          },
          {
            'title': 'Stress Management Techniques',
            'body':
                'Effective strategies include regular exercise, mindfulness meditation, deep breathing exercises, yoga, and maintaining social connections. Even small daily practices can make a meaningful difference in stress levels over time.',
          },
          {
            'title': 'Sleep and Stress Recovery',
            'body':
                'Quality sleep is essential for cortisol regulation and hormonal recovery. Aim for seven to nine hours per night, maintain a consistent sleep schedule, and create a calming bedtime routine to support your body\'s natural rhythms.',
          },
          {
            'title': 'When Professional Help Is Needed',
            'body':
                'If stress is affecting your health, relationships, or ability to function, consider seeking help from a counsellor or psychologist. Your doctor can also assess whether stress has caused hormonal changes that may need medical treatment.',
          },
        ],
        sectionsKn: [
          {
            'title': 'ಒತ್ತಡ ಹಾರ್ಮೋನ್‌ಗಳ ಮೇಲೆ ಹೇಗೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ',
            'body':
                'ದೇಹವು ಒತ್ತಡದಲ್ಲಿರುವಾಗ, adrenal ಗ್ರಂಥಿಗಳು cortisol ಮತ್ತು adrenaline ಬಿಡುಗಡೆ ಮಾಡುತ್ತವೆ. ದೀರ್ಘಕಾಲಿಕ ಒತ್ತಡವು cortisol ಮಟ್ಟವನ್ನು ಹೆಚ್ಚಿಸಿ, ಸಂತಾನೋತ್ಪತ್ತಿ ಹಾರ್ಮೋನ್‌ಗಳು, thyroid ಕಾರ್ಯ ಮತ್ತು insulin ನಿಯಂತ್ರಣದ ಸಮತೋಲನವನ್ನು ಅಡ್ಡಿಪಡಿಸಬಹುದು.',
          },
