        sectionsEn: [
          {
            'title': 'What Is the Pelvic Floor?',
            'body':
                'The pelvic floor is a group of muscles and connective tissues that stretch like a hammock from the pubic bone to the tailbone. These muscles support the bladder, uterus, and bowel, and play a key role in continence and sexual function.',
          },
          {
            'title': 'Why Pelvic Floor Exercises Matter',
            'body':
