          },
          {
            'title': 'How to Identify Your Pelvic Floor Muscles',
            'body':
                'Imagine you are trying to stop the flow of urine midstream or hold in wind — the muscles you squeeze are your pelvic floor muscles. Avoid tightening your abdomen, buttocks, or thighs while performing this action.',
          },
          {
            'title': 'How to Do Kegel Exercises',
            'body':
                'Squeeze your pelvic floor muscles, hold for up to ten seconds, then relax for the same duration. Aim for three sets of ten repetitions each day. You can do these exercises in any position — sitting, standing, or lying down.',
          },
          {
            'title': 'Progressing Your Exercises',
            'body':
                'Start with shorter holds if ten seconds is too difficult and gradually increase the duration as your muscles strengthen. You can also add quick, rapid squeezes to train the fast-twitch muscle fibres that respond to sudden pressure like coughing or sneezing.',
          },
          {
            'title': 'When to Expect Results',
            'body':
