          {
            'title': 'ಶ್ರೋಣಿ ತಳ ಎಂದರೇನು?',
            'body':
                'ಶ್ರೋಣಿ ತಳವು ಪ್ಯೂಬಿಕ್ ಮೂಳೆಯಿಂದ ಬಾಲದ ಮೂಳೆಯವರೆಗೆ ಜೋಲಿಯಂತೆ ಹರಡಿರುವ ಸ್ನಾಯುಗಳು ಮತ್ತು ಸಂಯೋಜಕ ಅಂಗಾಂಶಗಳ ಗುಂಪಾಗಿದೆ. ಈ ಸ್ನಾಯುಗಳು ಮೂತ್ರಕೋಶ, ಗರ್ಭಾಶಯ ಮತ್ತು ಕರುಳನ್ನು ಬೆಂಬಲಿಸುತ್ತವೆ ಮತ್ತು ಮೂತ್ರ ನಿಯಂತ್ರಣ ಹಾಗೂ ಲೈಂಗಿಕ ಕಾರ್ಯದಲ್ಲಿ ಪ್ರಮುಖ ಪಾತ್ರ ವಹಿಸುತ್ತವೆ.',
          },
          {
            'title': 'ಶ್ರೋಣಿ ತಳದ ವ್ಯಾಯಾಮಗಳು ಏಕೆ ಮುಖ್ಯ',
            'body':
                'ಗರ್ಭಧಾರಣೆ, ಹೆರಿಗೆ, ವಯಸ್ಸಾಗುವಿಕೆ, ಬೊಜ್ಜು ಮತ್ತು ದೀರ್ಘಕಾಲಿಕ ಒತ್ತಡ ಶ್ರೋಣಿ ತಳವನ್ನು ದುರ್ಬಲಗೊಳಿಸಬಹುದು. ಈ ಸ್ನಾಯುಗಳನ್ನು ಬಲಪಡಿಸುವುದು ಮೂತ್ರ ಅನಿಯಂತ್ರಣ ಮತ್ತು ಶ್ರೋಣಿ ಅಂಗ ಕುಸಿತವನ್ನು ತಡೆಯಲು ಮತ್ತು ಚಿಕಿತ್ಸೆ ನೀಡಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ ಮತ್ತು ಲೈಂಗಿಕ ತೃಪ್ತಿಯನ್ನು ಸುಧಾರಿಸಬಹುದು.',
