          {
            'title': 'ನಿಮ್ಮ ಶ್ರೋಣಿ ತಳದ ಸ್ನಾಯುಗಳನ್ನು ಗುರುತಿಸುವುದು',
            'body':
                'ಮೂತ್ರ ಹರಿವನ್ನು ಮಧ್ಯದಲ್ಲಿ ನಿಲ್ಲಿಸಲು ಅಥವಾ ಗಾಳಿ ಹಿಡಿಯಲು ಪ್ರಯತ್ನಿಸುತ್ತಿರುವುದನ್ನು ಊಹಿಸಿಕೊಳ್ಳಿ — ನೀವು ಬಿಗಿಗೊಳಿಸುವ ಸ್ನಾಯುಗಳೇ ನಿಮ್ಮ ಶ್ರೋಣಿ ತಳದ ಸ್ನಾಯುಗಳು. ಈ ಕ್ರಿಯೆ ಮಾಡುವಾಗ ನಿಮ್ಮ ಹೊಟ್ಟೆ, ಪೃಷ್ಠ ಅಥವಾ ತೊಡೆಗಳನ್ನು ಬಿಗಿಗೊಳಿಸದಿರಿ.',
