                'ನಿಮ್ಮ ಶ್ರೋಣಿ ತಳದ ಸ್ನಾಯುಗಳನ್ನು ಬಿಗಿಗೊಳಿಸಿ, ಹತ್ತು ಸೆಕೆಂಡುಗಳವರೆಗೆ ಹಿಡಿದಿಟ್ಟುಕೊಳ್ಳಿ, ನಂತರ ಅಷ್ಟೇ ಅವಧಿಗೆ ಸಡಿಲಿಸಿ. ಪ್ರತಿ ದಿನ ಹತ್ತು ಪುನರಾವರ್ತನೆಗಳ ಮೂರು ಸೆಟ್‌ಗಳನ್ನು ಗುರಿಯಾಗಿಸಿ. ಈ ವ್ಯಾಯಾಮಗಳನ್ನು ಕುಳಿತು, ನಿಂತು ಅಥವಾ ಮಲಗಿ ಯಾವುದೇ ಸ್ಥಾನದಲ್ಲಿ ಮಾಡಬಹುದು.',
          },
          {
            'title': 'ನಿಮ್ಮ ವ್ಯಾಯಾಮಗಳನ್ನು ಮುಂದುವರಿಸುವುದು',
            'body':
                'ಹತ್ತು ಸೆಕೆಂಡು ತುಂಬಾ ಕಷ್ಟವಾದರೆ ಕಡಿಮೆ ಅವಧಿಯ ಹಿಡಿತಗಳಿಂದ ಪ್ರಾರಂಭಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಸ್ನಾಯುಗಳು ಬಲವಾಗಿದಂತೆ ಕ್ರಮೇಣ ಅವಧಿಯನ್ನು ಹೆಚ್ಚಿಸಿ. ಕೆಮ್ಮು ಅಥವಾ ಸೀನಿನಂತಹ ಹಠಾತ್ ಒತ್ತಡಕ್ಕೆ ಪ್ರತಿಕ್ರಿಯಿಸುವ ವೇಗದ ಸ್ನಾಯು ತಂತುಗಳನ್ನು ತರಬೇತಿ ಮಾಡಲು ತ್ವರಿತ ಬಿಗಿತಗಳನ್ನೂ ಸೇರಿಸಬಹುದು.',
