        sectionsEn: [
          {
            'title': 'What Is Pelvic Organ Prolapse?',
            'body':
                'Pelvic organ prolapse occurs when the pelvic floor muscles and tissues weaken, allowing one or more pelvic organs (bladder, uterus, or rectum) to descend into or through the vagina. It is a common condition, particularly after childbirth and menopause.',
          },
          {
            'title': 'Types of Prolapse',
            'body':
