            'title': 'ಶ್ರೋಣಿ ಅಂಗ ಕುಸಿತ ಎಂದರೇನು?',
            'body':
                'ಶ್ರೋಣಿ ಅಂಗ ಕುಸಿತ ಶ್ರೋಣಿ ತಳದ ಸ್ನಾಯುಗಳು ಮತ್ತು ಅಂಗಾಂಶಗಳು ದುರ್ಬಲವಾಗಿ ಒಂದು ಅಥವಾ ಹೆಚ್ಚು ಶ್ರೋಣಿ ಅಂಗಗಳು (ಮೂತ್ರಕೋಶ, ಗರ್ಭಾಶಯ ಅಥವಾ ಮಲಾಶಯ) ಯೋನಿಯೊಳಗೆ ಅಥವಾ ಮೂಲಕ ಇಳಿಯುವಾಗ ಸಂಭವಿಸುತ್ತದೆ. ವಿಶೇಷವಾಗಿ ಹೆರಿಗೆ ಮತ್ತು ಋತುಬಂಧದ ನಂತರ ಇದು ಸಾಮಾನ್ಯ ಸ್ಥಿತಿಯಾಗಿದೆ.',
          },
          {
            'title': 'ಕುಸಿತದ ವಿಧಗಳು',
            'body':
                'Cystocele ಎಂದರೆ ಮೂತ್ರಕೋಶ ಮುಂಭಾಗದ ಯೋನಿ ಗೋಡೆಯೊಳಗೆ ಇಳಿಯುವುದು, ಗರ್ಭಾಶಯ ಕುಸಿತ ಎಂದರೆ ಗರ್ಭಾಶಯದ ಇಳಿಕೆ, ಮತ್ತು rectocele ಎಂದರೆ ಮಲಾಶಯ ಹಿಂಭಾಗದ ಯೋನಿ ಗೋಡೆಯೊಳಗೆ ಒತ್ತುವುದು. ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ವಿಧ ಏಕಕಾಲದಲ್ಲಿ ಸಂಭವಿಸಬಹುದು.',
          },
          {
            'title': 'ಲಕ್ಷಣಗಳು',
