            'title': 'ಮಹಿಳೆಯರು ಏಕೆ ಹೆಚ್ಚು ಪ್ರಭಾವಿತರಾಗುತ್ತಾರೆ',
            'body':
                'ಮಹಿಳೆಯರಿಗೆ ಪುರುಷರಿಗಿಂತ ಹೆಚ್ಚಿನ ಅಪಾಯವಿದೆ ಏಕೆಂದರೆ ಅವರಿಗೆ ಸಣ್ಣ, ತೆಳ್ಳನೆಯ ಮೂಳೆಗಳಿವೆ ಮತ್ತು ಋತುಬಂಧದಲ್ಲಿ oestrogen ಮಟ್ಟ ತೀವ್ರವಾಗಿ ಇಳಿಯುತ್ತದೆ, ಇದು ಮೂಳೆ ನಷ್ಟವನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ. ಋತುಬಂಧದ ನಂತರ ಐದು ರಿಂದ ಏಳು ವರ್ಷಗಳಲ್ಲಿ 20 ಪ್ರತಿಶತದಷ್ಟು ಮೂಳೆ ಸಾಂದ್ರತೆ ಕಳೆದುಹೋಗಬಹುದು.',
          },
          {
            'title': 'ಅಪಾಯಕಾರಿ ಅಂಶಗಳು',
            'body':
                'ಅಪಾಯಕಾರಿ ಅಂಶಗಳಲ್ಲಿ ಹೆಚ್ಚುತ್ತಿರುವ ವಯಸ್ಸು, ಆಸ್ಟಿಯೊಪೊರೋಸಿಸ್‌ನ ಕುಟುಂಬ ಇತಿಹಾಸ, ಕಡಿಮೆ ದೇಹ ತೂಕ, ಧೂಮಪಾನ, ಅತಿಯಾದ ಮದ್ಯಪಾನ, ವ್ಯಾಯಾಮದ ಕೊರತೆ ಮತ್ತು corticosteroids ನಂತಹ ಕೆಲವು ಔಷಧಗಳ ದೀರ್ಘಕಾಲೀನ ಬಳಕೆ ಸೇರಿವೆ. ಆರಂಭಿಕ ಋತುಬಂಧವೂ ಅಪಾಯವನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.',
          },
          {
            'title': 'ಸಾಮಾನ್ಯ ಮುರಿತ ಸ್ಥಳಗಳು',
