          },
          {
            'title': 'ರೋಗನಿರ್ಣಯ',
            'body':
                'ಆಸ್ಟಿಯೊಪೊರೋಸಿಸ್ ಅನ್ನು ಮೂಳೆ ಖನಿಜ ಸಾಂದ್ರತೆಯನ್ನು ಅಳೆಯುವ DEXA ಸ್ಕ್ಯಾನ್‌ನಿಂದ ರೋಗನಿರ್ಣಯ ಮಾಡಲಾಗುತ್ತದೆ. ಮೂಳೆ ಸಾಂದ್ರತೆಯ ಜೊತೆ ಇತರ ಅಪಾಯಕಾರಿ ಅಂಶಗಳನ್ನು ಪರಿಗಣಿಸುವ ಸಾಧನಗಳನ್ನು ಬಳಸಿ ನಿಮ್ಮ ವೈದ್ಯರು ನಿಮ್ಮ ಒಟ್ಟಾರೆ ಮುರಿತ ಅಪಾಯವನ್ನು ನಿರ್ಣಯಿಸಬಹುದು.',
          },
          {
            'title': 'ಚಿಕಿತ್ಸಾ ಆಯ್ಕೆಗಳು',
