          },
          {
            'title': 'Why It Happens',
            'body':
                'Oestrogen keeps the vaginal tissues thick, elastic, and well-lubricated. When oestrogen levels fall after menopause, the vaginal lining becomes thinner and less resilient, and natural lubrication decreases significantly.',
          },
          {
            'title': 'Non-Hormonal Treatments',
