            'title': 'How Menopause Increases Risk',
            'body':
                'After menopause, the decline in oestrogen leads to unfavourable changes in cholesterol levels, blood pressure, and blood vessel flexibility. These changes can accelerate the development of atherosclerosis (hardening of the arteries).',
