          },
          {
            'title': 'ಋತುಬಂಧ ಅಪಾಯವನ್ನು ಹೇಗೆ ಹೆಚ್ಚಿಸುತ್ತದೆ',
            'body':
                'ಋತುಬಂಧದ ನಂತರ oestrogen ಇಳಿಕೆ cholesterol ಮಟ್ಟಗಳು, ರಕ್ತದೊತ್ತಡ ಮತ್ತು ರಕ್ತನಾಳ ನಮ್ಯತೆಯಲ್ಲಿ ಪ್ರತಿಕೂಲ ಬದಲಾವಣೆಗಳಿಗೆ ಕಾರಣವಾಗುತ್ತದೆ. ಈ ಬದಲಾವಣೆಗಳು atherosclerosis (ಅಪಧಮನಿಗಳ ಗಟ್ಟಿಯಾಗುವಿಕೆ) ಬೆಳವಣಿಗೆಯನ್ನು ವೇಗಗೊಳಿಸಬಹುದು.',
